// Chunk templates for project operations, generated by
// scripts/projectops-templates.ts from py-aep-authored projects on the AE 25.6
// fixture base. Every clone is a fresh tree: patching it never touches the
// template or another clone.
import { readRifx, type Chunk, type RifxFile } from "../aep/riff.ts";
import data from "./data/project-templates.json" with { type: "json" };

export type TemplateBlock = "FOLDER" | "COMP" | "PNG" | "JPEG" | "MP4" | "SEQ" | "LAYERS" | "SOLIDS";

const decoded = new Map<string, RifxFile>();

function decode(key: string, base64: string): RifxFile {
  let file = decoded.get(key);
  if (!file) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    file = readRifx(bytes);
    decoded.set(key, file);
  }
  return file;
}

export function cloneChunk(chunk: Chunk): Chunk {
  const copy: Chunk = { ...chunk, offset: -1, data: chunk.data.slice() };
  if (chunk.children) copy.children = chunk.children.map(cloneChunk);
  if (chunk.tail) copy.tail = chunk.tail.slice();
  return copy;
}

/** An empty AE 25.6 project: 8 bpc, no working space, no items, empty render queue. */
export function emptyProjectFile(): RifxFile {
  const file = decode("empty", data.empty);
  return { root: cloneChunk(file.root), xmp: "", trailer: new Uint8Array(0) };
}

/** A fresh copy of a template item block: its `LIST:Item` first, then its view data. */
export function templateBlock(name: TemplateBlock): Chunk[] {
  const base64 = (data.blocks as Record<string, string>)[name];
  if (!base64) throw new Error(`no project template "${name}"`);
  return (decode(name, base64).root.children ?? []).map(cloneChunk);
}
